    if (res.code === '200') {
      const data = unwrapData(res.data) || {}
      graphData.value = {
        enabled: Boolean(data.enabled),
        nodes: Array.isArray(data.nodes) ? data.nodes : [],
        relations: Array.isArray(data.relations) ? data.relations : []
      }
      return
    }
    graphData.value = { enabled: false, nodes: [], relations: [] }
  } finally {
    loading.value = false
  }
}

